const TOKEN = $env.HOMELAB_TELEGRAM_BOT_TOKEN, CHAT = String($env.HOMELAB_TELEGRAM_CHAT_ID || '');
const LAN = 'http://192.168.3.201', PVE = 'https://192.168.3.200:8006';
const helpers = this.helpers;
const s = $getWorkflowStaticData('global');
const say = (text) => helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${TOKEN}/sendMessage`, body: { chat_id: CHAT, text, disable_web_page_preview: true }, json: true, timeout: 15000 });
const get = (url, opts = {}) => helpers.httpRequest({ url, json: true, timeout: 20000, ...opts });
const safe = async (fn) => { try { return await fn(); } catch (e) { return null; } };
const lagosNow = () => new Date(new Date().toLocaleString('en-US', { timeZone: 'Africa/Lagos' }));
const pad = (n) => String(n).padStart(2, '0');
const ymd = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const hm = (h) => { const m = Math.round(h * 60); return Math.floor(m / 60) ? `${Math.floor(m / 60)} h ${m % 60} min` : `${m % 60} min`; };
const prom = async (expr) => { const r = await get(`${LAN}:9090/api/v1/query`, { qs: { query: expr } }); const v = r?.data?.result?.[0]?.value?.[1]; return v === undefined ? null : Number(v); };
const pveGet = (path) => get(`${PVE}/api2/json${path}`, { headers: { Authorization: `PVEAPIToken=${$env.HOMEPAGE_VAR_PROXMOX_TOKEN_ID}=${$env.HOMEPAGE_VAR_PROXMOX_TOKEN_SECRET}` }, skipSslCertificateValidation: true }).then(r => r.data);
const ghHeaders = (extra = {}) => ({ Authorization: `Bearer ${$env.HOMELAB_GITHUB_TOKEN || ''}`, Accept: 'application/vnd.github+json', 'User-Agent': 'homelab-n8n', ...extra });
const gh = (path, opts = {}) => { const { headers, ...rest } = opts; return helpers.httpRequest({ url: `https://api.github.com${path}`, json: true, timeout: 20000, headers: ghHeaders(headers), ...rest }); };
const REPO = $env.HOMELAB_GITHUB_REPO || 'theOGpython/homelab';

// Power advice: solar surplus, grid-off low battery, heavy load, and the evening (5pm) grid-off warning.
const SURPLUS_W = 400, FULL_SOC = 95, LOW_SOC = 40, HEAVY_W = 2000, OVERHEAD_W = 100;
const d = await get(`${LAN}:9878/json`, { timeout: 10000 });
if (d.bat_soc === undefined) return [];
const now = Date.now(), t = lagosNow(), hour = t.getHours() + t.getMinutes() / 60, today = ymd(t);
const grid = d.grid_present >= 1, soc = Math.round(d.bat_soc), pv = d.pv_power || 0, load = d.load_power || 0;
const spare = Math.round(pv - load - OVERHEAD_W);
const night = d.night_runtime_hours !== undefined ? hm(d.night_runtime_hours) : null;
const out = [];

// 1) Solar to spare: battery full, daytime, surplus seen on two checks in a row, at most every 3 hours
if (hour >= 9 && hour < 16 && soc >= FULL_SOC && spare >= SURPLUS_W) s.surplusSeen = (s.surplusSeen || 0) + 1; else s.surplusSeen = 0;
if (s.surplusSeen >= 2 && now - (s.lastSurplus || 0) > 3 * 3600e3) {
  out.push(`☀️ Battery ${soc}% and about ${spare} W of solar to spare. Good time for the iron, washing machine or pumping water.`);
  s.lastSurplus = now;
}

// 2) Grid off and battery getting low: once per drop (re-arms above 50%)
if (s.lowArmed === undefined) s.lowArmed = true;
if (!grid && soc <= LOW_SOC && s.lowArmed) {
  out.push(`🔋 Grid off and battery at ${soc}%. Avoid heavy appliances for now.` + (night ? `\nAt the current load (${Math.round(load)} W) it lasts about ${night} without solar.` : ''));
  s.lowArmed = false;
}
if (soc >= 50) s.lowArmed = true;

// 3) Heavy load on battery (recommended max 2 kW): two checks in a row, at most every 30 minutes
if (!grid && load >= HEAVY_W) s.heavySeen = (s.heavySeen || 0) + 1; else s.heavySeen = 0;
if (s.heavySeen >= 2 && now - (s.lastHeavy || 0) > 30 * 60e3) {
  out.push(`⚡ The house is drawing ${(load / 1000).toFixed(1)} kW from the battery (recommended max 2 kW). Switch something heavy off if you can.`);
  s.lastHeavy = now;
}

// 4) Evening: from 5pm until 9pm, the first time the grid is off each day
if (hour >= 17 && hour < 21 && !grid && s.eveningDate !== today) {
  out.push(`🌇 The sun is setting and the grid is off. Battery ${soc}%, solar fading (${Math.round(pv)} W).\nTo get through the night, switch off heavy loads: iron, kettle, AC, pumping machine.` +
    (night ? `\nAt the current load (${Math.round(load)} W) the battery lasts about ${night}.` : ''));
  s.eveningDate = today;
}

for (const text of out) await say(text);
return out.length ? [{ json: { sent: out.length } }] : [];
